const euro = new Intl.NumberFormat("en-IE", { style: "currency", currency: "EUR", maximumFractionDigits: 0 });
const number = new Intl.NumberFormat("en-IE");
const escapeHtml = (value) => String(value ?? "").replace(/[&<>'"]/g, (char) => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", "'":"&#39;", '"':"&quot;" })[char]);
const money = (value) => value < 0 ? `(${euro.format(Math.abs(value))})` : euro.format(value);
const nav = (page) => `<header class="topbar"><div class="topbar-inner"><a class="brand" href="/"><span class="brand-mark">D</span><span>Divorce Party International Ltd.<small>Financial Reconstruction</small></span></a><nav class="nav" aria-label="Primary"><a href="/" ${page==="overview"?'aria-current="page"':""}>Overview</a><a href="/review/" ${page==="review"?'aria-current="page"':""}>Decision review</a></nav></div></header>`;
const status = (text, cls="") => `<span class="pill ${cls}">${escapeHtml(text)}</span>`;
function evidenceClass(text){ return text.includes("E01")||text.includes("E02")||text.includes("E03")||text.includes("E06")||text.includes("E09")||text.includes("E10") ? "high" : text.includes("E11")||text.includes("E12") ? "low" : ""; }
function statementRows(statement, trace) { return Object.entries(statement).map(([key,value]) => { const item=trace[key]||{}; const label=key.replace(/([A-Z])/g," $1").replace(/^./,c=>c.toUpperCase()); return `<tr class="${/profitForPeriod|closingCash|totalAssets|totalLiabilitiesAndEquity|netCashFromOperatingActivities|netCashUsedInInvestingActivities|netCashUsedInFinancingActivities/.test(key)?"total":""}"><td>${label}${item.evidence?.length?`<a class="trace-link" href="#sources">Trace ${item.decisionIds.join(", ")}</a>`:""}</td><td class="number ${value<0?"negative":""}">${money(value)}</td></tr>`; }).join(""); }
function overview(data){ const s=data.statements, trail=data.aiReviewTrail, trace=data.traceability; const checks=Object.entries(data.finalTraceabilityCheck.reconciliations); const e=data.evidence;
 return `${nav("overview")}<div class="shell"><p class="eyebrow">Certified financial analysis · Student ${escapeHtml(data.student.name)}</p><h1>Financial Reconstruction at 31 August 2026</h1><p class="lede">Evidence-based review of financial statements, decisions, reconciliations, uncertainty, and board recommendation.</p><div class="status-row">${status("100 decisions complete")}${status("All reconciliations passed")}${status("EUR 9,000 inventory uncertainty","warn")}${status("Owner-only review ready","neutral")}</div><section class="metrics"><article class="metric"><span class="label">Certified profit</span><strong>${money(s.profitAndLoss.profitForPeriod)}</strong><small>January–August 2026</small></article><article class="metric"><span class="label">Closing cash</span><strong>${money(s.cashFlow.closingCash)}</strong><small>Agrees to bank confirmation</small></article><article class="metric"><span class="label">Closing equity</span><strong>${money(s.balanceSheet.equity)}</strong><small>Positive, but thin against liabilities</small></article></section><section class="grid"><article class="card inventory-card"><h2>Inventory judgment — visible uncertainty</h2><p>The physical count is the chosen measurement basis because it directly observes the 31 August stock position.</p><div class="callout"><strong>${money(121000)} closing saleable inventory</strong><br><span class="muted">EUR 79,000 Finally Single materials + EUR 42,000 Never Call Back materials.</span></div><ul><li><strong>Chosen treatment:</strong> material COGS ${money(396000)} and separate write-down ${money(22000)}.</li><li><strong>Alternative considered:</strong> the EUR 405,000 stated consumption figure would create a ${money(9000)} downside to inventory, profit and equity.</li><li><strong>Rejected adjustment:</strong> no ${money(2000)} disposal provision—the quote does not evidence a present obligation.</li></ul>${status("Medium confidence · investigation required","warn")}</article><article class="card"><h2>Evidence hierarchy</h2><p class="muted">The register privileges evidence by source reliability, not by the confidence of a management assertion.</p><div class="evidence-list"><div class="evidence high"><b>High · Bank, signed contracts and external confirmations</b><small>Controls cash, debt, revenue cut-off, receivables and provisions.</small></div><div class="evidence high"><b>High · Third-party invoices and goods received</b><small>Controls purchases, payables, equipment and repair classification.</small></div><div class="evidence"><b>Medium · Warehouse, CRM and payroll records</b><small>Supports inventory, web-sales delivery and functional payroll split.</small></div><div class="evidence low"><b>Low · Management workbook and messages</b><small>Explains pressure and conflicts; does not control the outcome.</small></div></div></article></section><section class="section"><div><h2>Assessor checks</h2><p>Every result below is independently reconciled in the certified submission.</p></div><a class="trace-link" href="/review/">Open the 100-decision register →</a></section><section class="grid equal"><article class="card"><ul class="check-list">${checks.map(([name,check])=>`<li><span class="check">✓</span><span><strong>${escapeHtml(name.replace(/([A-Z])/g," $1"))}</strong><br><span class="muted">${escapeHtml(check.calculation)}</span></span></li>`).join("")}</ul></article><article class="card"><h2>AI review trail</h2><div class="agent-grid"><div class="agent agent1"><b>Agent 1</b><p>${money(trail.agent1OriginalPosition.profit)} profit<br>No disposal provision</p></div><div class="agent agent2"><b>Agent 2</b><p>${money(trail.agent2OriginalPosition.profit)} profit<br>Included ${money(trail.agent2OriginalPosition.disposalProvision)} provision</p></div><div class="agent approved"><b>Certified</b><p>${money(trail.approvedCertifiedResult.profit)} profit<br>Agent 2 provision overruled</p></div></div><p class="muted" style="margin-top:12px;font-size:13px">The agents' positions are retained as review inputs. The final certified answers follow approved analysis and original evidence.</p></article></section><section class="section"><div><h2>Certified financial statements</h2><p>Click each statement-line trace link to see its supporting decision IDs in the review register.</p></div></section><section class="statement-grid">${[["Profit and loss",s.profitAndLoss,trace.financialStatements.profitAndLoss],["Cash flow",s.cashFlow,trace.financialStatements.cashFlow],["Balance sheet",s.balanceSheet,trace.financialStatements.balanceSheet]].map(([title,values,links])=>`<article class="card statement"><h3>${title}</h3><table><tbody>${statementRows(values,links)}</tbody></table></article>`).join("")}</section><section id="sources" class="section"><div><h2>Named evidence register</h2><p>All numbered references flow into the decision register and statement traceability map.</p></div></section><section class="card"><ul class="source-list">${e.map(item=>`<li><code>${escapeHtml(item.id)}</code> ${escapeHtml(item.description)}</li>`).join("")}</ul></section><p class="footer">Prepared as a certified, traceable reconstruction for review. VAT and corporate income tax are outside scope.</p></div>`; }
function review(data){ return `${nav("review")}<div class="shell"><div class="review-header"><div><p class="eyebrow">Assessor review</p><h1>Complete decision register</h1><p class="lede">All 100 decisions remain visible. Material judgments preserve both original AI positions and the certified student resolution.</p></div><div class="status-row">${status("75 operational")}${status("25 material judgments")}${status(data.finalTraceabilityCheck.decisionCoverage.materialJudgmentsWithAgentDisagreement.length + " AI disagreements","alert")}</div></div><section class="card tight"><div class="metrics" style="margin:0"><article><strong class="number">100</strong><br><span class="muted">Required IDs present</span></article><article><strong class="number">${data.finalTraceabilityCheck.statementAndScheduleTraceability.supportingScheduleLinesTraced + data.finalTraceabilityCheck.statementAndScheduleTraceability.financialStatementLinesTraced}</strong><br><span class="muted">Traced statement and schedule lines</span></article><article><strong class="number">7/7</strong><br><span class="muted">Reconciliations passed</span></article></div></section><div class="filters"><label>Search answer, question or evidence<input id="search" type="search" placeholder="e.g. inventory, D058, liquidation"></label><label>Review tier<select id="tier"><option value="">All tiers</option><option value="material_judgment">Material judgment</option><option value="operational">Operational</option></select></label><label>Attention<select id="attention"><option value="">All decisions</option><option value="disagreement">AI disagreement</option><option value="overrule">Student override</option><option value="medium">Medium confidence</option></select></label><button id="reset" type="button">Reset filters</button></div><p id="result-count" class="meta"></p><div class="decision-table-wrap"><table class="decision-table"><thead><tr><th>ID</th><th>Decision</th><th>Certified answer</th><th>Evidence and review</th><th>Confidence</th></tr></thead><tbody id="decision-body"></tbody></table></div><p class="footer">Yellow tags mark material judgments. Red flags identify a genuine difference between the two AI analyses; the final certified answer remains decisive.</p></div>`; }
function decisionRow(d){ const effect=Object.entries(d.statementEffect||{}).filter(([,v])=>v!==null).map(([k,v])=>`${k}: ${money(v)}`).join(" · ")||d.statementEffectNarrative||"No direct statement entry"; const material=d.reviewTier==="material_judgment"; return `<tr><td class="id-cell">${d.id}<br><span class="badge ${material?"material":"operational"}">${material?"Material":"Operational"}</span></td><td><strong>${escapeHtml(d.question)}</strong><br>${d.agentsDisagreed?'<span class="flag">● AI disagreement</span> ':""}${d.overruledAI?'<span class="flag">Student override recorded</span>':""}</td><td class="answer-cell"><p>${escapeHtml(d.certifiedFinalAnswer||d.answer)}</p>${material?`<details><summary>Review trail and statement effect</summary><div class="detail-grid"><div><b>Agent 1</b><p>${escapeHtml(d.aiProposal)}</p><b>Agent 2</b><p>${escapeHtml(d.independentChallenge)}</p></div><div><b>Student reasoning</b><p>${escapeHtml(d.studentReasoning)}</p><b>Statement effect</b><p>${escapeHtml(effect)}</p><b>Overruled AI?</b><p>${escapeHtml(d.overruledAIAnswer||"No")}</p></div></div></details>`:""}</td><td>${d.evidence.map(x=>`<div class="meta">${escapeHtml(x)}</div>`).join("")}</td><td><span class="badge ${d.confidence}">${escapeHtml(d.confidence)}</span></td></tr>`; }
function startReview(data){ const body=document.querySelector("#decision-body"), count=document.querySelector("#result-count"); const controls={search:document.querySelector("#search"),tier:document.querySelector("#tier"),attention:document.querySelector("#attention")}; const draw=()=>{const query=controls.search.value.toLowerCase().trim();const rows=data.decisions.filter(d=>{const hay=[d.id,d.question,d.answer,d.certifiedFinalAnswer,...d.evidence].join(" ").toLowerCase();return (!query||hay.includes(query))&&(!controls.tier.value||d.reviewTier===controls.tier.value)&&(!controls.attention.value||(controls.attention.value==="disagreement"&&d.agentsDisagreed)||(controls.attention.value==="overrule"&&d.overruledAI)||(controls.attention.value==="medium"&&d.confidence==="medium"));});body.innerHTML=rows.length?rows.map(decisionRow).join(""):`<tr><td colspan="5"><div class="empty">No decisions match these filters.</div></td></tr>`;count.textContent=`Showing ${rows.length} of ${data.decisions.length} decisions.`;};Object.values(controls).forEach(c=>c.addEventListener("input",draw));document.querySelector("#reset").addEventListener("click",()=>{controls.search.value="";controls.tier.value="";controls.attention.value="";draw();});draw(); registerWebMcp(data,controls,draw);}
function registerWebMcp(data,controls,draw){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();try{void Promise.resolve(context.registerTool({name:"filter_decision_register",title:"Filter decision register",description:"Filter the visible assessor register by review tier, confidence, or decision search text.",inputSchema:{type:"object",properties:{query:{type:"string"},tier:{type:"string",enum:["","operational","material_judgment"]},attention:{type:"string",enum:["","disagreement","overrule","medium"]}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(typeof input!=="object"||input===null)throw new Error("Filter input must be an object.");controls.search.value=typeof input.query==="string"?input.query:"";controls.tier.value=["","operational","material_judgment"].includes(input.tier)?input.tier:"";controls.attention.value=["","disagreement","overrule","medium"].includes(input.attention)?input.attention:"";draw();return {visibleFilters:{query:controls.search.value,tier:controls.tier.value,attention:controls.attention.value},totalDecisions:data.decisions.length};}}, {signal:lifecycle.signal})).catch(()=>{});}catch{} }
function addBoardSection(data){ const target=[...document.querySelectorAll(".section")].find(section=>section.textContent.includes("Certified financial statements")); if(!target)return; const board=data.boardRecommendation; target.insertAdjacentHTML("beforebegin", `<section class="section board-heading"><div><h2>Material uncertainty and board recommendation</h2><p>Approved treatment, its remaining exposure, and the actions required before the business can continue safely.</p></div></section><section class="grid equal board-grid"><article class="card uncertainty-card"><p class="eyebrow">Material uncertainty</p><h3>€9,000 inventory discrepancy</h3><p><strong>Physical-count outcome used:</strong> closing saleable inventory of €121,000.</p><p><strong>Alternative consumption-based outcome:</strong> inventory, profit and equity could each be €9,000 lower.</p><p><strong>Action required:</strong> investigate and reconcile the warehouse records immediately.</p>${status("Medium confidence · immediate investigation required","warn")}</article><article class="card recommendation-card"><p class="eyebrow">Board recommendation</p><h3>Continue only with immediate controls</h3><p>${escapeHtml(board.conclusion)}</p><p class="muted">${escapeHtml(board.workingCapital)} ${escapeHtml(board.solvency)}</p><ul>${board.immediateControls.map(item=>`<li>${escapeHtml(item)}</li>`).join("")}</ul></article></section>`); }
async function main(){ const app=document.querySelector("#app"); try{const response=await fetch("/submission.json");if(!response.ok)throw new Error("Submission data unavailable");const data=await response.json();const page=document.body.dataset.page;app.innerHTML=page==="review"?review(data):overview(data);if(page==="review")startReview(data);else addBoardSection(data);}catch(error){app.innerHTML=`${nav("overview")}<div class="shell"><div class="card" style="margin-top:32px"><h1>Review data unavailable</h1><p class="lede">The certified submission could not be loaded. Please refresh the page.</p></div></div>`;} }
main();
